// FUNCTION: BFME2 0x00129690 size=86 name=?Rva00129690@@YAXXZ evidence=?:placeholder
void Debug_Statistics::Record_Draw_Call_Batch()
{
	int count = DrawCallBatchCount;
	if (count >= MAX_DRAW_CALL_BATCHES) {
		return;
	}

	if (count == 0) {
		DrawCallBatches[0] = RunningDrawCalls;
	} else {
		int previousDrawCalls = 0;
		for (int i = 0; i < count; ++i) {
			previousDrawCalls += DrawCallBatches[i];
		}
		DrawCallBatches[count] = RunningDrawCalls - previousDrawCalls;
	}
	DrawCallBatchCount = count + 1;
}


